-- Generated by tools/generate_native_encounter_library.py from the public Bastion Library export.
return {
  ["katta-vampyre-troubles-autarkic-lord-sfarosh"] = {overview = {"The questioning of Autarkic Lord Sfarosh ends with a fight against him and three shadow allies."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Allow the ritual dialogue to progress through the assembled spellcasters; the hostile encounter begins at its conclusion.", "Sfarosh’s combat form appears with three shadow creatures. Have tanks ready for the simultaneous arrival.", "The hostile Sfarosh immediately attacks the character recorded by the ritual. Complete the fight before his scripted cleanup, about twelve minutes after spawning."}}}},
  ["kerraridge-tissa-sovereign-of-terror-and-the-nine-lives-of-kerra"] = {overview = {"Weaken Tissa by defeating her eight generals, or face the Sovereign of Terror at full strength."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Enter A Fur-midable Cat-ch through Multiverse MacBeth after completing the introductory dialogue. The event requires the Kerra content flag and a nonzero instance.", "Each general defeated reduces Tissa’s maximum health, melee damage and resistances. Clearing more generals makes the final confrontation easier.", "Ahed splits at half health. Dou brings kittens into the fight. Siete progressively resists physical attacks, requiring the group to adapt its damage.", "Ath must be finished by a cleric, druid or shaman; an incorrect finishing class causes the encounter to repeat.", "Milestones for defeated generals provide additional chests. Defeating Tissa without weakening her creates a separate full-strength bonus.", "Tissa’s death clears her remaining forces. Return the requested proof to MacBeth to complete the adventure."}}}},
  ["kithicor-blackened-treant-and-blackened-dryad"] = {overview = {"A blackened treant breaks apart into limbs before the dryad emerges."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeat the Blackened Treant, then gather the Blackened Tree Limbs that replace it.", "The limbs lead to the Blackened Dryad. Keep the group together through the successive spawns so the new target does not reach an unprepared player.", "The dryad casts Withering Glare seven seconds after engagement and every twenty seconds thereafter. Keep healing ready for the top-hate target."}}}},
  ["kithicor-cloaked-figure-shadow-thief"] = {overview = {"A cloaked figure draws a bard into a shadow ambush that ends only when the shadow thief is defeated."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"A bard at the appropriate epic stage hails the cloaked figure. Ten seconds later, four malignant shadows appear around the bard and attack.", "Each shadow immediately replaces itself on death. After the tenth shadow kill, a shadow thief appears at the dead shadow’s location.", "Switch to the thief when it arrives; repeatedly clearing shadows alone will not end the fight.", "The thief casts an additional spell at 25% health. Its death removes every remaining shadow and begins the event cooldown."}}}},
  ["kodtaz-pixtt-grand-summoner-ring"] = {overview = {"Break the summoner ring through priests, stoneservants and a final Chaos Provoker sequence."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Begin by defeating the nine Priest Summoners. Fighting the priests also brings Rav Priest Guardians into the ring.", "Once the priests are gone, lesser and greater stoneservants appear. Their deaths reduce the Grand Summoner’s health and bring replacement golems until he is sufficiently weakened.", "The golems take increased blunt-weapon damage and reduced slashing and archery damage. Choose weapons accordingly.", "Keep the battle near the center of the ring. Pulling the linked opponents too far away clears hate and restores their health.", "Defeat the exposed Grand Summoner to bring out the Hexxt Chaos Provoker. The Provoker’s death produces a final group of supreme stoneservants."}}}},
  ["kodtaz-temple-of-the-damned"] = {overview = {"Disturb the Temple of the Damned’s bones, defeat four guardians and expose the summoner."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Destroying the bone pile summons four Priest Guardians and a protected summoner.", "Kill all four guardians to make the summoner attackable.", "The event has a fifteen-minute cleanup timer that pauses while the summoner is engaged.", "The available summoner depends on the temple’s current respawn state. The alternate version follows the same combat sequence but does not carry the main loot pool."}}}},
  ["nightmareb-terris-thule"] = {overview = {"Terris Thule calls dream defilers and animated statues while trapping the raid inside her nightmare."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Keep Terris inside her lair. Pulling her outside the scripted boundaries despawns her.", "At 75% health, fifteen dream defilers appear: eight use the mezzable template and seven use the unmezzable template. Assign crowd control and tanks accordingly.", "At 50%, she casts Direption of Dreams; at 45%, Defilement of Hope targets the top of her hate list.", "At 35%, four statues animate. Pick them up while the raid finishes Terris.", "After victory, speak with the planar projection for progression credit."}}}},
  ["lakeofillomen-vorash-deep-and-xenevorash"] = {overview = {"Confront Vorash and Deep, then prepare for Xenevorash to appear as Vorash falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Vorash and Deep automatically attack monks who approach within their proximity area. Bring support before entering that space.", "Vorash’s death directly summons Xenevorash. Prepare a tank and healing for the new arrival before delivering the finishing blow.", "Control Deep while completing the sequence; the active Vorash handler does not wait for Deep to die before summoning Xenevorash."}}}},
  ["lakerathe-kazen-fecae-undead-trial"] = {overview = {"Kazen Fecae tests a necromancer with a chain of undead opponents."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete Kazen’s challenge hand-in with the group ready for the bone golem.", "The bone golem’s death summons the next undead challenger at the ritual site.", "Remain for the full succession of opponents and complete Kazen’s requested follow-up rather than leaving after the first kill."}}}},
  ["lakerathe-man-eating-freshwater-shark"] = {overview = {"The man-eating freshwater shark becomes more dangerous as it loses health."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Its maximum melee hit increases at 75%, 50% and 25% health. Save tank support for the later part of the fight.", "Keep the shark controlled while crossing each threshold, allowing healers to adjust before the next push.", "The summoned shark despawns thirty minutes after appearing, so prepare before triggering the encounter."}}}},
  ["delvea-a-halfling-s-greed"] = {overview = {"Clear the chest guards and open the treasures in the correct order."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Inspect the chests and clear their guards before committing to an opening.", "The required opening order is gold, cracked, gilded, then silver.", "Opening a later chest while an earlier one remains triggers Meddler's Misfortune and ends the mission."}}}},
  ["delvea-lavaspinner-hunting"] = {overview = {"Hunt lavaspinners until the mission eggs appear."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Kill lavaspinners to advance the egg-spawn checks.", "Watch for the ground-shaking announcement and search for each new egg.", "Continue through the cracked eggs to the pristine egg and complete the mission's collection objectives."}}}},
  ["delvea-stonemaw"] = {overview = {"Stonemaw enters combat with three supporting enemies."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare to collect Magma, Molten and Smolder when Stonemaw is engaged.", "Keep the boss tank covered while the group reduces the three-add pressure.", "An out-of-combat timer removes the summoned support after an extended break."}}}},
  ["delvea-the-drake-menace-drake-matriarch"] = {overview = {"Destroy the drake eggs and prepare for the matriarch's retaliation."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear drakes and keep watch for the mission's egg progression.", "Expect additional drakes as eggs are destroyed.", "Destroying the fifteenth egg calls the Drake Matriarch; prepare the group before breaking the last egg."}}}},
  ["delvea-volkara-s-bite"] = {overview = {"Volkara drops egg sacs at health thresholds that soon hatch into spiderlings."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"At 80%, 60%, 40%, 20% and 10%, expect a new egg sequence.", "Deal with egg sacs before their thirty-second hatch timer when possible.", "Keep an add tank ready for magma spiderlings and avoid pushing several thresholds together."}}}},
  ["lavastorm-high-priestess-shima-ambush"] = {overview = {"Laura Rako’s quest exchange brings High Priestess Shima and her priestly escort into Lavastorm."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Prepare before the triggering hand-in: Shima arrives with five priest adds.", "Assign tanks or control to the escort before committing damage to the High Priestess.", "Complete the quest’s requested follow-up after the ambush is defeated."}}}},
  ["lfaydark-taskmaster-mirot-and-the-reanimated-minions"] = {overview = {"Taskmaster Mirot and his reanimated minions fight as a linked group."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The quest sequence summons Mirot with six minions. Engaging either the taskmaster or a minion pulls other linked opponents into combat.", "Minions taken more than 200 units from Mirot are brought back to him. Plan to control the group nearby rather than splitting them across the forest.", "The summoned taskmaster has a thirty-minute cleanup timer. Finish the fight and recover the quest objective within that window."}}}},
  ["provinggrounds-lightning-warrior-spiritseeker"] = {overview = {"An eligible shaman awakens the Lightning Warrior Spiritseeker and its two spiritsappers."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Approaching the stilled warrior at the appropriate epic stage replaces it with the Spiritseeker.", "Engaging the Spiritseeker summons two lightning warrior spiritsappers at its location. Establish add control immediately.", "After disengagement, a fifteen-minute cleanup timer removes the Spiritseeker and its spiritsappers."}}}},
  ["chamberse-mastery-of-adaptation"] = {overview = {"Adapt to constructs whose changing forms alter resistances and combat abilities."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Identify the active form before committing your strongest attacks.", "Favor cold against the fire form and fire against the ice form.", "Keep extra healing available for the forms with rampage or flurry.", "Pick up supporting constructs as they appear and adjust weapon choices to the current form."}}}},
  ["chambersf-mastery-of-corruption"] = {overview = {"Defeat increasingly large groups of adventurer-like opponents."}, roles = {}, phases = {{label = "First wave", trigger = "Challenge begins", description = "Defeat the initial party of six class-based enemies."}, {label = "Second wave", trigger = "First wave defeated", description = "Collect the larger party and control its casters and healers."}, {label = "Final wave", trigger = "Second wave defeated", description = "Defeat the largest party to complete the trial."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The three waves grow from a small balanced party to a much larger force.", "Assign control for healers and dangerous casters while tanks collect the melee enemies.", "Expect class-specific tricks, including monk recovery and wizard positioning behavior.", "Keep the fighting inside the trial area."}}}},
  ["chambersf-mastery-of-destruction"] = {overview = {"Defeat enough attackers to expose the Master of Destruction, then finish him."}, roles = {}, phases = {{label = "Initial opponents", trigger = "Before twenty kills", description = "Defeat twenty trial enemies while preserving resources."}, {label = "Master of Destruction", trigger = "Twenty kills reached", description = "Defeat the master before the trial timer expires."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Kill twenty of the trial enemies to activate the master.", "Keep the group moving from target to target so the initial enemies do not consume the time budget.", "Save enough resources for the master; the entire trial lasts fifteen minutes."}}}},
  ["chambersd-mastery-of-efficiency"] = {overview = {"Clear timed waves while fighting under the Test of Efficiency debuff."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Expect the trial debuff to be maintained throughout the encounter.", "Use resources carefully and finish the active enemies before later waves arrive.", "Complete the wave sequence within the fifteen-minute trial."}}}},
  ["chambersb-mastery-of-endurance"] = {overview = {"Survive a twenty-minute assault with coordinated control and sustained healing."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for a survival fight rather than a quick boss burn.", "Collect each new wave and use crowd control to keep the number of active attackers manageable.", "Conserve mana and rotate defensive abilities so the raid can survive the full twenty minutes."}}}},
  ["chambersa-mastery-of-fear"] = {overview = {"Use fear to control susceptible enemies while defeating the fearless attackers."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Begin only when everyone is ready for the fifteen-minute trial.", "Keep fear on susceptible enemies; the script drains their health while they are feared.", "Defeat at least fifteen of the fearless enemies before the timer expires."}}}},
  ["chambersc-mastery-of-foresight"] = {overview = {"Follow personal and raid warnings to survive the Trial of Foresight."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Move to the announced safe side when the room heats up.", "Read your kyv warning carefully: it may require moving, standing still or ducking.", "Remove the specified rings or main-hand weapon when the equipment warning appears.", "Watch dragorn preparations and respond with distance or focused damage as the warning directs."}}}},
  ["chambersa-mastery-of-hate"] = {overview = {"Clear the ferans, then rotate tanks to control the Master of Hate's growing damage."}, roles = {}, phases = {{label = "Feran mothers", trigger = "Opening", description = "Defeat the six mothers while controlling the direpups."}, {label = "Master of Hate", trigger = "All mothers defeated", description = "Rotate the top-threat tank to reset the growing maximum hit."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Kill the feran mothers while controlling the direpups they produce.", "When the master activates, rotate the top-threat tank deliberately.", "His maximum hit rises while one tank remains on top; a detected tank change resets that escalation."}}}},
  ["chamberse-mastery-of-ingenuity"] = {overview = {"Defeat the Master of Ingenuity while reflection and pet pressure limit easy damage."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Watch for Reflective Sheen every forty-five seconds before casting into the master.", "Damage shields are repeatedly removed from players on the hate list.", "Pets on the hate list are hit by a heavy attack every three minutes.", "Finish the master within the fifteen-minute trial."}}}},
  ["chambersd-mastery-of-specialization"] = {overview = {"The Master of Specialization cycles through spells that test the raid's adaptability."}, roles = {}, phases = {}, abilities = {{name = "Specialization spell cycle", summary = "A repeating sequence of eight spells.", description = {"Imprecision, Searing Pain, Rigidity, Chilling Agony, Curse of Misfortune, Glimmering Aura, Impurity and Toxic Blast are cast in order."}, tags = {"Adaptation"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for a new spell in the scripted rotation every twenty-five seconds.", "Adjust damage and support as each effect changes which tools are effective.", "Maintain tank healing throughout the alternating weakening and damaging casts."}}}},
  ["chambersc-mastery-of-subversion"] = {overview = {"Recover enough seals to challenge the Master of Subversion."}, roles = {}, phases = {{label = "Recover seals", trigger = "Below 300 points", description = "Gather copper, silver and gold seals to reach the required total."}, {label = "The master", trigger = "300 points reached", description = "Prepare to defeat the now-vulnerable Master of Subversion."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Collect seals until their combined value reaches 300 points.", "Copper, silver and gold seals contribute 10, 20 and 30 points respectively.", "Avoid unnecessary fighting while gathering, then prepare to defeat the master when the required total is reached."}}}},
  ["chambersb-mastery-of-weaponry"] = {overview = {"Defeat four opponents by adapting your weapons to their vulnerabilities."}, roles = {}, phases = {{label = "Weapon opponents", trigger = "Four sequential activations", description = "Defeat the opponents in the randomized activation order, matching weapon types to each vulnerability."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Use slashing against the Hulking Bazu.", "Use piercing, backstab or archery against Hemkai the Ascendant.", "Use blunt or hand-to-hand attacks against the Granite Stoneguardian.", "Steelshock strongly reduces most weapon damage; reserve spell damage for this opponent."}}}},
  ["soldungb-lord-nagafen-seasonal"] = {overview = {"Seasonal Nagafen adds health-gated reinforcements and spell attacks to his chamber fight."}, roles = {{id = "everyone", label = "Everyone", tips = {"Plan add pickup before crossing 70% and 40% and keep the current tank supported through spell thresholds."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Three random reinforcements appear at 70% health and again at 40%.", "Additional targeted spells trigger at 60%, 30% and 10% health.", "Keep the fight in his chamber; combat includes a boundary check and banishment handling."}}}},
  ["natimbi-cragbeast-queen-seasonal"] = {overview = {"The seasonal Cragbeast Queen favors piercing weapons and calls nearby creatures to her defense."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Use piercing or two-handed piercing attacks where possible. The script increases those damage types while sharply reducing blunt, slashing, archery and throwing damage.", "Every forty-five seconds in combat, the Queen draws idle creatures within a wide surrounding area onto her top-hate target.", "Clear the nearby shore before the pull and keep an add tank ready for the call-for-help emote.", "Leaving combat stops the repeated assist calls."}}}},
  ["natimbi-ritual-conduit"] = {overview = {"Defeat the ritual’s Reborn, expose the Conduit and finish the Noc Juggernaut it releases."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The Conduit starts protected with ten Reborn nearby. Six Reborn deaths make it attackable.", "At 30% health, the Conduit is replaced by a Noc Juggernaut. Keep the tank ready for the new target.", "The Juggernaut uses Energy Conduit seven seconds after engagement, then every twenty seconds.", "Both principal enemies must stay close to the ritual site; leaving the leash area heals them and clears hate.", "The event’s spawned stages have fifteen-minute cleanup timers. Avoid a long pause during the transition."}}}},
  ["natimbi-spiritbinder-trenzar-and-senvial-of-the-mist"] = {overview = {"Break Spiritbinder Trenzar’s hold over Senvial of the Mist."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Trenzar creates a bound elemental every ten seconds and brings the elementals onto the group’s hate list. Keep add control active throughout the fight.", "Wave of Flame begins fourteen seconds after engagement and repeats every twenty seconds.", "Senvial appears after a random delay of seventy-five to one hundred twenty seconds. Bring Senvial to 10% health and defeat Trenzar to release the spirit.", "Once Senvial stops fighting, the eligible ranger should hail the freed spirit to advance the epic quest."}}}},
  ["natimbi-tybone-biggums"] = {overview = {"Strip away Tybone’s armored and fleshy forms in the Skin and Bones expedition."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete the two gathering sets, then use Tybone’s give chase dialogue to request the group expedition.", "The opening armored form favors blunt weapons. At 67% health, two dominated defenders appear and Tybone becomes untargetable until both are defeated.", "The middle form favors non-blunt weapons. At 34%, two mastruq defenders appear and protect him through another transition.", "After both defenders die, the final skeletal form again favors blunt damage. Re-establish the tank after each transition because Tybone clears his hate list.", "Keep alternate weapon types available and finish each defender pair before trying to damage Tybone again."}}}},
  ["causeway-alpha-feran"] = {overview = {"Alpha Feran calls other ferans into the fight."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Expect the first call ten seconds after engagement and further calls every fifteen seconds.", "Control nearby ferans before committing to the boss.", "Have a tank collect any ferans brought into combat by the howl."}}}},
  ["causeway-bazu-smasher"] = {overview = {"Bazu Smasher repeatedly calls pairs of hulks as its health falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Plan for two hulks at each of 90%, 75%, 70%, 55%, 50%, 35%, 30%, 15% and 10%.", "Control damage near adjacent thresholds so the group can collect each pair.", "An extended disengagement clears the summoned hulks."}}}},
  ["causeway-bazu-terror"] = {overview = {"Defeat Bazu Terror and its crushers to expose the dark animist."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible beastlord starts the event through Jillaa Oogblat.", "Be ready for four bazu crushers alongside the boss.", "Bazu Terror's death summons the dark animist at its position.", "The bazu stage has a thirty-minute appearance window."}}}},
  ["causeway-essence-of-kreljnok"] = {overview = {"Kreljnok calls adds that dramatically increase his regeneration while alive."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Collect Kreljnok's Power and Kreljnok's Rage when they appear.", "Prioritize those adds to return the boss's regeneration to its lower state.", "A new pair is called every 150 seconds during combat; finish before the thirty-minute appearance ends."}}}},
  ["causeway-magician1-5-elemental-mastery-event"] = {overview = {"Defeat successive elemental splits to expose the Essence of Air again."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible magician activates the encounter by reaching its hidden trigger.", "At 80%, 60%, 40%, 20% and 10%, the essence disappears and summons a larger set of lesser essences.", "Kill every essence of the current set to make the boss return.", "Tanks should rebuild threat after each return; complete the sequence inside thirty minutes."}}}},
  ["causeway-oshiruk"] = {overview = {"Oshiruk repeatedly casts Tendrils during the bard epic finale."}, roles = {}, phases = {}, abilities = {{name = "Tendrils of Oshiruk", summary = "A recurring cast directed at the current target.", description = {}, tags = {"Recurring spell"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep the tank and nearby group covered for a Tendrils cast every twelve seconds.", "Recover between casts while maintaining steady damage."}}}},
  ["causeway-siflu"] = {overview = {"Subdue Siflu and speak with him after the Muramite control breaks."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Lower Siflu to 15% health rather than expecting a death completion.", "Once he becomes immune and stops fighting, the eligible ranger should follow the adventurers dialogue.", "Complete the encounter and dialogue before his fifteen-minute appearance ends."}}}},
  ["causeway-slavedriver-menlo"] = {overview = {"Menlo repeatedly forces refugee groups into battle."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep a tank available for refugees while the main tank holds Menlo.", "A new refugee group is called every minute, cycling through five groups.", "Idle refugees can be drawn into the fight between calls, so watch the whole area."}}}},
  ["causeway-stone-thrower"] = {overview = {"The seasonal Stone Thrower pressures both close and distant players."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Watch personal warnings and reposition before their ten-second impact.", "For the reviewed rock-blast logic, finish within 100 units of the boss; targets beyond that distance take the hit.", "When targeted by the distant-player grip, move within 150 units before it resolves.", "Keep the main tank covered for recurring boulder strikes."}}}},
  ["causeway-withering-murkglider"] = {overview = {"Withering Murkglider releases parasites repeatedly as its health falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Expect three parasitic murkgliders at 99%, 79%, 59%, 39% and 19%.", "Control the parasites before pushing through another threshold.", "A disengagement fully heals the boss and rearms the sequence."}}}},
  ["northkarana-dire-griffon-plains-dragon-transformation"] = {overview = {"A dire griffon changes into a plains dragon when reduced below 80% health."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Prepare the group before crossing the griffon’s health threshold.", "The griffon disappears and the dragon appears in its place. Switch targets and establish the dragon on the tank immediately.", "If the dragon is already present, the script waits rather than summoning another copy."}}}},
  ["qeynos2-enchanted-rat-experiment"] = {overview = {"Give Velarte the research briefing at the appropriate badge quest stage. A random four-by-four board appears and an 18-minute timer begins.", "Trade each filled rat jar to an empty tile. The released rat cures diseased rats in straight cardinal lines when they lie between it and the nearest healthy rat in that direction.", "Use all three jars, cure every diseased rat, and return the three empty jars together to Velarte before the experiment times out."}, roles = {}, phases = {}, abilities = {}, sections = {}},
  ["oasis-remal-the-black"] = {overview = {"Protect Keelee through a personal paladin trial, then pursue Remal to the orc camp."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"An eligible paladin hails Keelee to start. During the initial ritual, other nearby characters are banished away; the initiator must handle the waves.", "Four waves of four orcs arrive at two-minute intervals. All orcs must be dead when the final wave timer is checked or the event fails.", "On success, Keelee and Remal move to another orc camp and Remal becomes attackable. Follow Keelee’s shout to the new location.", "Defeat Remal within the final one-hour window, then the initiating paladin must hail Keelee for credit."}}}},
  ["sebilis-sebilite-protector"] = {overview = {"Test the berserker's trial weapons against the Sebilite Protector while dealing with his guardians."}, roles = {{id = "everyone", label = "Everyone", tips = {"Control the guardians and their healing while the questing berserker completes each weapon test."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The qualifying juggernaut kill checks the berserker's epic step and event cooldown before spawning the protector and two guardians.", "At 75% health, the protector begins Death Shackles and signals the guardians into their spell cycle.", "Guardians cast debuffs and repeatedly attempt Complete Heal on the protector.", "The qualifying berserker must perform the weapon tests during combat; the encounter has a 30-minute despawn deadline."}}}},
  ["sebilis-trakanon-seasonal"] = {overview = {"Trakanon alternates close-range bile, random deathgaze and a banishment of his leading target."}, roles = {{id = "everyone", label = "Everyone", tips = {"Arrange a tank handoff when the current target is banished and keep healers ready for simultaneous damage."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Bile bursts every 20 seconds within 70 range; deathgaze checks a random hate target every 40 seconds.", "Every 30 seconds, the leading client or pet owner is moved away and reduced to minimal hate.", "At 20% health, scripted timers stop and several slashing, piercing and blunt attacks gain increased damage taken."}}}},
  ["permafrost-lady-vox-seasonal"] = {overview = {"Seasonal Lady Vox calls ice creatures and adds spell attacks at key health thresholds."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Two ice adds appear at 70% health and three more at 40%. Reserve tanks and control for both waves.", "Vox casts additional scripted spells at 60%, 30% and 10%. Prepare tank support before crossing those thresholds.", "Keep Vox near her lair’s spawn area. Her combat routine checks the leash continuously.", "The seasonal version uses a different appearance and permits the expedition’s higher-level participants; the ordinary version’s level-based banishment is not used here."}}}},
  ["fearplane-cazic-thule"] = {overview = {"Cazic Thule calls much of the Plane of Fear to defend him."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear the surrounding zone before engaging Cazic Thule.", "The opening call adds most surviving zone NPCs to the top-threat target's hate list.", "Keep spare tanks and control available for any enemies that arrive after the pull."}}}},
  ["fearplane-cazic-thule-static-mode"] = {overview = {"Static-mode Cazic Thule combines zone reinforcements, fear and growing physical vulnerability."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear the zone before the pull; the initial call can bring surviving enemies to the main target.", "Collect the nightmare minions summoned at 70% and 40%.", "Prepare for fear casts at 60% and 30%.", "Players within 60 units take a scripted terror pulse every forty seconds.", "Slashing, two-handed blunt and one-handed piercing attacks gain increased effectiveness at 50%, with a larger vulnerability at 20%."}}}},
  ["fearplane-dracoliche-static-mode"] = {overview = {"The static-mode dracoliche reassembles after nearly being defeated."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Cover nearby players for the necrotic breath pulse every twenty-five seconds.", "Save enough resources for another push: at 1%, the dracoliche restores itself to 35% health.", "Pick up the two fetid fiends that appear during reanimation.", "A disengagement clears the adds and rearms the reanimation sequence."}}}},
  ["fearplane-fear-touched-dracolich-ambush"] = {overview = {"Qualifying kills can trigger a Fear-Touched Dracolich ambush."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"During the associated active task, keep the group ready after each kill.", "The ambush can appear at the slain enemy's location and immediately attack the credited player.", "A tank should collect the dracolich before the group moves on."}}}},
  ["fearplane-fear-golems-dread-fright-and-terror"] = {overview = {"Dread and Fright use recurring Death Touch; all three golems can leave a broodling behind."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Have the pull and recovery plan ready before engaging Dread or Fright: the first Death Touch can occur almost immediately.", "Further Death Touch casts repeat every forty-five seconds against the top-threat target.", "A pet at the top of the hate list redirects the cast to its owner; the script also removes listed divine-aura protections.", "After any golem dies, check for the possible iksar broodling."}}}},
  ["fearplane-ireblind-imp"] = {overview = {"The Ireblind Imp releases groups of rage essences at three health thresholds."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for three essences at each of 76%, 51% and 26%.", "Collect and control the essences before pushing into the next threshold.", "Keep the imp tank covered while damage dealers manage each new group."}}}},
  ["growthplane-tunare"] = {overview = {"Engaging the Tunare in the tree replaces her with the ground encounter. The active content flag selects either normal Tunare or the Fabled Tunare.", "Normal Tunare adds the attacker to the hate lists of nearly all non-pet NPCs in the zone, with a small explicit exception list. Clear or prepare for the forest before beginning the fight."}, roles = {}, phases = {}, abilities = {{name = "Forest assistance", summary = "Tunare calls the surrounding forest into the battle.", description = {"Normal Tunare calls the zone on combat entry. Fabled Tunare instead moves a defined list of NPC types toward her and repeats that call every six minutes while engaged."}, tags = {}, roles = {}}}, sections = {{title = "Fabled variant", paragraphs = {"The fabled_velious content flag selects the fabled ground form. Both variants are represented by this zone-version-0 entry because the script uses a content flag rather than a different zone version."}, bullets = {}}}},
  ["poinnovation-manaetic-behemoth"] = {overview = {"Stop the clockwork devices from feeding the inactive Manaetic Behemoth, then defeat its active form."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Intercept the devices before they reach their final waypoint and release an energy burst. Leave a team on each approach while preparing the main tank.", "The dormant Behemoth uses a three-minute activation counter influenced by device bursts. Keep the incoming devices controlled until the active form appears.", "The active Behemoth has a twenty-minute hard despawn. Fight inside its room to avoid its positional leash.", "Its death advances the local gnome’s progression dialogue."}}}},
  ["poinnovation-nitram-anizok-xanamech-nezmirthafen"] = {overview = {"Help Nitram Anizok activate Xanamech Nezmirthafen, then defeat the construct and return to Nitram."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete Nitram’s three-component hand-in and accompany him along his route to the inactive dragon.", "At the activation point, the real Xanamech replaces the inactive model. Prepare the group before Nitram arrives.", "The attempt has a two-hour failure timer. After Xanamech falls, return to Nitram promptly: the victory state resets after ten minutes."}}}},
  ["pojustice-the-seventh-hammer"] = {overview = {"Face the Seventh Hammer in the chamber of judgment."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The Seventh Hammer offers a challenge through its judgment dialogue. Assemble the group before accepting.", "When the Tribunal cycle is active, the encounter alternates judgments on a seventy-five-second timer after its opening warning.", "Keep healing ready for repeated area pressure and defeat the Hammer before leaving the chamber."}}}},
  ["pojustice-trial-of-execution"] = {overview = {"Save the prisoner from execution through four waves, then defeat Prime Executioner Vathoch."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each wave brings four enemies while the executioner moves toward the prisoner. The executioner moves faster with each new wave.", "Killing a wave enemy interrupts the executioner and sends it back when more enemies remain. Use those kills to buy time, then finish the wave.", "Do not allow the executioner to remain at the prisoner. Its execution timer causes the trial to fail.", "After the fourth wave is cleared, defeat Vathoch to complete the trial."}}}},
  ["pojustice-trial-of-flame"] = {overview = {"Survive four waves and the trial’s flame pressure, then defeat the Punisher of Flame."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The first wave begins after twenty seconds. Four enemies arrive in each wave, with subsequent waves scheduled ninety seconds apart.", "The flame controller activates during the trial. Keep the group healed while clearing enemies before the next timed wave.", "Defeat every enemy from the fourth wave to summon the Punisher of Flame."}}}},
  ["pojustice-trial-of-hanging"] = {overview = {"Prevent the prisoners from suffocating and defeat Gallows Master Teion."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each round brings ordinary enemies and two suffocating spirits, with the second spirit arriving forty-five seconds after the first.", "Spirits threaten different prisoners. Prioritize them as they appear; killing a spirit provides relief to its prisoner.", "Every two spirit kills advances the next round. After eight spirits have been defeated, Gallows Master Teion appears.", "Keep the prisoners alive through the final fight to finish the trial."}}}},
  ["pojustice-trial-of-lashing"] = {overview = {"Break the spirits sustaining the Scourge before it reaches the prisoners, then defeat Lashman Azakal."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each round begins with four enemies. Thirty seconds later, three Flickering Spirits appear and an invulnerable Scourge moves toward a prisoner.", "Kill all three spirits to remove the Scourge. Spending damage on the invulnerable Scourge delays the rescue.", "Complete four spirit rounds while controlling the other enemies, then defeat Lashman Azakal."}}}},
  ["pojustice-trial-of-stoning"] = {overview = {"Protect the accused from their avengers through four waves and defeat Yurae Zhaleem."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Four enemies arrive per wave on a ninety-second schedule. Avengers threaten the accused while enemies remain alive.", "Clear the active wave quickly to remove the avengers and stop their pressure on the prisoners.", "The sixteenth required wave kill summons Yurae Zhaleem. Establish the boss tank while protecting the survivors."}}}},
  ["pojustice-trial-of-torture"] = {overview = {"Keep the tortured prisoners alive through four enemy waves, then defeat Punisher Veshtaq."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Four-enemy waves arrive two minutes apart. Pick up every incoming enemy before it reaches the prisoners.", "Clearing an early wave summons a Wraith of Agony. Defeat it to produce the relief effect for the trial.", "After all sixteen wave enemies are defeated, Punisher Veshtaq appears. Finish the boss while maintaining protection of the prisoners."}}}},
  ["poknowledge-bonded-hunts-companion-challenges-36-targets"] = {overview = {"Take a companion challenge from the Curator of Bonded Echoes and defeat an owner-bound echo with your own pet or charmed companion."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Visit the Curator of Bonded Echoes in the Plane of Knowledge to select an eligible assignment. The system supports shadow knights, druids, bards, shamans, necromancers, magicians, enchanters and beastlords.", "Travel to the assignment’s target zone and activate the hunt beacon. The echo appears beside you and scales to at least your level plus two, subject to the target’s own level.", "Only you and your pet or charmed companion may enter the echo’s hate list for the victory audit to pass. Avoid assistance that would involve another character in the fight.", "Druids, bards and enchanters receive an accompanying creature for the charm approach. Establish your companion before committing to the echo.", "The echo expires after twenty minutes. A failed audit leaves the assignment available to retry.", "After an accepted victory, return to the curator. Recharge assignments require carrying the assigned partially charged physical wand before activating the hunt."}}, {title = "Hunt destinations", paragraphs = {"The curator offers thirty-six targets across these zones. The assignment identifies the exact echo and destination."}, bullets = {"The Hole", "The Ruins of Old Guk", "Ocean of Tears", "The Jaggedpine Forest", "Veksar", "The Temple of Droga", "The Ruins of Sebilis", "Chardok", "Cobaltscar", "The Western Wastes", "The Plane of Mischief", "The Great Divide", "The Paludal Caverns", "Ssraeshza Temple", "The Dawnshroud Peaks", "The Maiden's Eye", "The Plane of Nightmares", "The Plane of Disease", "The Plane of Water", "The Plane of Fire", "Dulak's Harbor", "The Torgiran Mines", "The Crypt of Nadox", "Hate's Fury", "Barindu, Hanging Gardens", "Qvic, Prayer Grounds of Calling", "Tipt, Treacherous Crags", "Sewers of Nihilia, Purifying Plant", "Wall of Slaughter", "Nobles' Causeway", "The Ruined City of Dranik", "Riftseekers' Sanctum", "The Broodlands", "Stillmoon Temple", "Thundercrest Isles", "Lavaspinner's Lair"}}}},
  ["mischiefplane-bristlebane-the-king-of-thieves-2-0"] = {overview = {"Bristlebane changes his defenses and attacks at every health stage while calling increasingly large groups of jesters."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeat the mischievous jester to summon the King of Thieves.", "Every ten-percent health step changes a combination of armor, resistances, melee damage and attack speed. Watch the rock-skin, glowing-aura and strength emotes.", "He summons two jesters at 80%, three at 50% and five at 20%. Prepare additional tanks and crowd control before these thresholds.", "Five minutes out of combat restores his health and opening state and removes his adds.", "His two-hour availability timer pauses while engaged and resumes outside combat."}}}},
  ["ponightmare-aid-eino-escort-dreamkeeper"] = {overview = {"Escort Aid Eino through successive nightmare ambushes and defeat the Dreamkeeper."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Stay close to Eino and immediately intercept the attackers targeting him. The route includes banshees, nightstalkers, hobgoblins and bats.", "The largest ambush combines three banshees with three bats. Preserve crowd control and healing for that stop.", "After a brief rest, Eino reaches the Dreamkeeper. Protect Eino while killing the boss, which despawns after sixty seconds without combat.", "Follow Eino to the return portal and complete the requested quest hand-in there."}}}},
  ["ponightmare-deyid-the-twisted"] = {overview = {"Deyid the Twisted closes a ring of trees around the raid before bringing part of it to life."}, roles = {}, phases = {{label = "Encirclement", trigger = "90% health", description = "A ring of eleven trees surrounds the fight."}, {label = "Closing ring", trigger = "60% and 50% health", description = "The trees move progressively closer."}, {label = "Living trees", trigger = "40% health", description = "Four trees become attackable opponents."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 90% health, eleven trees appear around the encounter.", "At 60% and 50%, the ring moves inward. Keep room to adjust your positioning as the trees close around you.", "At 40%, four trees become active enemies. Assign add control before crossing this threshold and maintain the main tank on Deyid.", "Deyid’s death removes the summoned trees and advances the local event."}}}},
  ["ponightmare-mujaki-the-devourer"] = {overview = {"Intercept the servants approaching Mujaki’s platform, then defeat Mujaki the Devourer."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear the nightmare steeds around the platform to start the event.", "Seven waves bring thirty-six servants in total from three grave sites. Intercept them before they reach the platform: unengaged servants that arrive become mounted riders.", "Each wave is timed, so avoid letting stronger riders and fresh servants accumulate together.", "When all thirty-six servants have either died or transformed, Mujaki becomes attackable. Control the remaining riders while defeating him."}}}},
  ["ponightmare-terror-matriarch"] = {overview = {"The Terror Matriarch continually produces hatchlings once the fight begins."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 98% health, the first abhorrent hatchling appears; another can spawn every thirty seconds while the Matriarch remains engaged.", "Assign someone to gather the hatchlings away from vulnerable group members while the main tank holds the Matriarch.", "Finish the boss before the recurring adds overwhelm the group. Each summoned hatchling has its own five-minute cleanup timer."}}}},
  ["postorms-drornok-tok-vo-lok"] = {overview = {"Clear the pond creatures to call Drornok Tok Vo’Lok, then handle two additional frog waves during the fight."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeat the required loktoles, amphans and toads around the pond to summon Drornok.", "Drornok repopulates the pond when he appears. Establish a controlled approach before pulling him.", "At 97% and 50% health, he summons two more pond creatures directly onto the tank’s hate target. Prepare an add tank at both thresholds.", "If he heals to 99%, his summoned combat adds are cleared and both health triggers reset."}}}},
  ["postorms-falto-lord-of-thunder"] = {overview = {"Clear the burning and blazing mephits to summon Falto, Lord of Thunder."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The event stages a decrepit ent and a field of mephits. The boss trigger specifically checks that no burning or blazing mephits remain.", "Sweep the whole event area for stragglers before expecting Falto to appear.", "Once the final required mephit is gone, gather the group at the trigger location and engage Falto."}}}},
  ["postorms-ston-ruak-ancient-of-trees"] = {overview = {"Clear the Koka’Vor defenders, defeat their reinforcements, and summon Ston’Ruak, Ancient of Trees."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"First clear the Koka’Vor krovians, senvars and chieftains monitored by the event.", "Eight elders or chieftains then appear in two groups of four: one in the boss chamber and one to the northwest.", "Defeat all eight reinforcements while keeping the original required defenders cleared. This summons Ston’Ruak in the chamber."}}}},
  ["potimeb-plane-of-time-phase-4-gods"] = {overview = {"Defeat Terris Thule, Saryrn, Tallon Zek and Vallon Zek to complete the fourth phase of the Plane of Time."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Terris Thule summons four adds at 91%, 51% and 11% health. Reserve add tanks for each threshold.", "Saryrn also summons four adds per wave, at 96%, 51% and 11%. Avoid crossing a fresh threshold while the previous wave is uncontrolled.", "Vallon creates two copies at 51% health. Hold those copies while continuing damage on the real Vallon.", "Keep Tallon and Vallon inside their tethered area. Leaving it returns the boss home and clears hate.", "Defeat all four gods to advance. Terris, Saryrn and Vallon reset their scripted stages after five minutes out of combat."}}}},
  ["potimeb-plane-of-time-phase-5-gods"] = {overview = {"Defeat Bertoxxulous, Cazic Thule, Innoruuk and Rallos Zek to open the final phase of the Plane of Time."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Bertoxxulous gains melee strength at 90%, 70% and 55%, while his spell resistances fall. Below 40%, 30% and 10%, those changes reverse. Plan the strongest tank support around the middle of the fight.", "Innoruuk summons three or four adds at 75%, then four or five at 20%. Establish add control before pushing either threshold.", "Rallos summons four adds at 90%, 75% and 50%, then five at 25%. At 75% he gains area rampage and faster attacks; at 50% he gains flurry; at 25% his attacks accelerate again.", "Maintain steady tank healing on Cazic Thule and finish all four gods to advance to Quarm."}}}},
  ["potimeb-plane-of-time-phases-1-3"] = {overview = {"Clear the five opening trials, their second-stage armies, and eight further waves to reach the gods of Time."}, roles = {}, phases = {{label = "Five trials", trigger = "Expedition begins", description = "Complete earth, air, undead, water and fire."}, {label = "Second formations", trigger = "All opening trials complete", description = "Clear the elemental armies and the undead sequence."}, {label = "Eight waves", trigger = "Phase two complete", description = "Defeat ten required enemies in each wave, then both final guardians."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Phase one contains the earth, air, undead, water and fire trials. Complete all five before the next phase opens.", "Phase two presents four elemental formations with their named leaders. The undead lane advances through groups of two, two and four guardians before Ralthos Enrok appears.", "Phase two completes only when all forty elemental kills and nine undead kills have been credited.", "Phase three runs eight waves, each advancing after ten required kills. The final pair is the Avatar of the Elements and the Supernatural Guardian.", "The expedition tracks phase lockouts and can resume at a later stage. Follow the zone’s timer announcements and avoid leaving required enemies alive behind the raid."}}}},
  ["potimeb-quarm"] = {overview = {"Quarm loses heads as its health falls, changing its area spells while renewing a trio of time vortexes."}, roles = {}, phases = {{label = "Four heads", trigger = "Pull to 76%", description = "Control three vortexes and the opening five-spell selection."}, {label = "Three heads", trigger = "76%", description = "Quarm loses the red head, clears its buffs and changes its spell set."}, {label = "Two heads", trigger = "51%", description = "The blue head is lost and the spell set changes again."}, {label = "Final head", trigger = "26%", description = "The white head is lost; finish Quarm through the final two-spell selection."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Three time vortexes appear almost immediately on engagement and are replaced every fifty seconds. Assign add control without losing pressure on Quarm.", "At 76%, 51% and 26% health, a head is destroyed. Each transition removes all buffs from Quarm and changes its available area spells.", "Area spells normally repeat every twenty-five seconds. A head transition resets that timer to six seconds, so prepare the raid for a quick follow-up.", "Reapply needed debuffs after each head loss. Keep healers ready as the spell set narrows through the final phase.", "Leaving combat removes the vortexes. Five minutes without combat restores Quarm’s health, heads and opening phase."}}}},
  ["potorment-baraguj-szuul-mouth-event"] = {overview = {"Fight through the mouth gauntlet, defeat an Unimaginable Horror, then confront the returned Baraguj Szuul."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The mouth event populates a descending gauntlet of enemies ending in an Unimaginable Horror.", "Defeating the Horror casts Dimensional Return on players within two hundred units and replaces the waiting Baraguj with the combat version.", "Regroup after the return before fighting Baraguj. His triggered form begins checking for an idle reset after fifteen minutes."}}}},
  ["potorment-keeper-of-sorrows-tylis-torment"] = {overview = {"Enter Tylis Newleaf’s torment, defeat the Keeper of Sorrows, and speak with the freed Tylis."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"An eligible character with the Shadyglade progression flag and the required key can tell Tylis that they will assist. Tylis moves that character’s group into the chamber.", "Defeat the Keeper of Sorrows to summon the freed Tylis and record the expedition’s Keeper completion.", "Hail the freed Tylis for progression credit, then gather within one hundred units before using the ready dialogue to return to the tower.", "The freed Tylis remains for thirty minutes. Complete the dialogue and return together during that window."}}}},
  ["potorment-maareq-the-prophet"] = {overview = {"Stop Maareq’s minions from reaching him while he transforms into an increasingly dangerous melee opponent."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"A minion appears every five seconds during combat. Any minion that gets within five units of Maareq is absorbed and heals him for 6,000 health.", "Intercept the minions on their approach instead of letting them collect at the boss.", "At 80%, Maareq grows. At 60%, he transforms and attacks faster. At 40%, he gains area rampage.", "Prepare melee healing for the final stage. His death removes the remaining minions and activates Tylis Newleaf."}}}},
  ["potorment-salczek-the-fleshgrinder"] = {overview = {"Salczek the Fleshgrinder becomes dangerous to nearby attackers as his health falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 40% health, Salczek gains area rampage. Keep vulnerable group members away from his melee range.", "At 20%, area rampage becomes more frequent. Reserve defensive abilities and additional melee healing for the finish.", "After five minutes out of combat, the scripted rampage state resets."}}}},
  ["potorment-saryrn"] = {overview = {"Saryrn calls repeated raven waves and brings Sorrowsong into direct combat near the end."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 98%, Saryrn signals Sorrowsong to begin singing.", "At every ten-percent threshold from 90% through 10%, Saryrn summons three or four servants or twisted spirits. Prepare add pickups before each health push.", "At 25%, Sorrowsong becomes an active opponent. Assign a tank for it before crossing that threshold.", "Keep add damage controlled through the last two raven waves and finish Saryrn. A planar projection appears after her death.", "Five minutes without combat resets the scripted health progression and restores Sorrowsong."}}}},
  ["povalor-aerin-dar"] = {overview = {"Aerin’Dar activates pairs of golem guards as the fight progresses."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Two golems activate at each of 80%, 60%, 40% and 20% health. They choose targets from Aerin’Dar’s hate list.", "At 20%, the named golem Rhalgon also activates. Reserve enough tanks and healing for the largest final wave.", "Control each pair before driving the boss through the next health threshold.", "If Aerin’Dar heals back to 98%, the golems repopulate and the health stages reset. Defeat the dragon and approach the planar projection."}}}},
  ["qinimi-execution-rescue-kreshin-silentcog"] = {overview = {"Hold the entry stone on your cursor and say \"I wish to enter\" near the device. Nearby group members within 75 paces are transported with you.", "Three waves activate on a fixed schedule. Kill them promptly so they do not overlap, then defeat Pixtt Tixxrt Kvrok to make the executioner vulnerable.", "Kill the executioner within the final three-minute window. After the rescue, show Kreshin the entry stone before the group is ejected."}, roles = {}, phases = {{label = "Opening waves", trigger = "Ten seconds after staging", description = "The first wave has two spiritbrutes and one bloodhunter. Two minutes later the second matching wave activates; two minutes after that, one spiritbrute and two bloodhunters activate."}, {label = "Pixtt and guards", trigger = "Two minutes after the third wave", description = "The Pixtt becomes active with two guards. The executioner begins moving and the three-minute failure timer starts."}, {label = "Stop the execution", trigger = "Pixtt defeated", description = "The executioner loses protection. Kill him to stop the failure timer."}, {label = "Speak to Kreshin", trigger = "Executioner defeated", description = "The party has seven minutes and thirty seconds before transport out, with a warning for the final twenty-five seconds."}}, abilities = {}, sections = {}},
  ["qinimi-mastruq-commander-gorlakt-and-the-spiritlords"] = {overview = {"An eligible druid approaching the trigger at the required epic stage summons Gorlakt and the two Spiritlords. This sets a two-hour event cooldown and a 30-minute cleanup timer.", "Gorlakt starts protected. The first Spiritlord death removes his protection and determines the spell he inherits: Mind Warp from Mind or Body Warp from Body.", "The first inherited spell choice persists. Killing the other Spiritlord does not grant him a second spell timer."}, roles = {}, phases = {}, abilities = {{name = "Mind Warp", summary = "Mind and a Mind-empowered Gorlakt cast on their current target.", description = {"The first cast follows a random five-to-fifteen-second delay, then repeats every thirty seconds."}, tags = {}, roles = {}}, {name = "Body Warp", summary = "Body and a Body-empowered Gorlakt cast on their current target.", description = {"The first cast follows a random five-to-twenty-second delay, then repeats every forty-five seconds."}, tags = {}, roles = {}}}, sections = {}},
  ["qinimi-thunderdome"] = {overview = {"At the required Qinimi quest stage, tell Councilman Sislono Nislan you are ready while in a raid with at least six members in the zone. He assigns an available chamber.", "In the reviewed first chamber, clear twenty-one opening enemies and three ratuks within ten minutes. The complete event has a separate twenty-seven-minute timer.", "After Kabeka falls, test the boss images by taking them to 90% health. Finding the real image advances the fight immediately; a false image removes the set and produces fewer choices."}, roles = {}, phases = {{label = "Chamber waves", trigger = "Event begins", description = "Six guardians spawn after five seconds, six noc and ukun at one minute, and nine more at three minutes. Clear all twenty-one."}, {label = "Three ratuks", trigger = "Opening enemies defeated", description = "Defeat the three ratuks. Completing this stage stops the first ten-minute deadline."}, {label = "Kabeka", trigger = "Three ratuks defeated", description = "Manage arrow volleys and the self-buff at 5% health."}, {label = "Find the real image", trigger = "Kabeka defeated", description = "Push images to 90% until the real boss appears. Wrong choices reduce the next set; exhausting the choices also produces the final boss."}, {label = "Final boss", trigger = "Real image identified", description = "Defeat the final incarnation before the overall deadline."}}, abilities = {}, sections = {}},
  ["drachnidhivec-sendaii-the-hive-queen"] = {overview = {"Survive the Hive Queen's waves, destroy her reflections and finish the final swarm."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear the staged hive defenders before committing to the queen.", "At 75%, Sendaii splits into reflections. Eliminate the false images before driving the real queen to 45%.", "At 45%, remaining images are absorbed and strengthen the queen.", "At 25%, prepare for the swarm and preserve enough healing to finish.", "Keep the final phase engaged; a prolonged loss of combat can reset it."}}}},
}
